from common import *
B='51冷血人.txt'
make('bai_kelau','白克劳',B,
'白克劳是从经营中积起巨大财富的富豪，拥有地产、珠宝业及汽车制造企业。他把不断工作与扩张视为生活本身，甚至休息也不能使他忘记资产增长。他秘密来城并非度假，而是追逐电脑研究员李诺的自动驾驶技术。新发明会迫使既有工厂改变结构，他因此不愿推广，只想买下并毁掉资料。李诺拒绝后，他派蒙蒂以珠宝展览的安全工作接近木兰花，又在谈判不成时派人炸毁住宅，差点害死安妮。他仍以只叫手下炸房子为自己辩解，这种把后果切割出去的习惯比简单的贪钱更能体现其逻辑。资料实际上藏在皮包握手内，他当众取出软片焚毁，达到了阻止技术流出的目标。后来专机出险，木兰花不计敌对关系救下所有乘客，他才亲自道谢并解释动机；但被救并未使他放弃把私人利益置于公共利益之上的立场。他不是李诺命案的主使，这一点由另一个犯罪集团成员的供述证实，不能因主角愤怒就给他添上未经发生的杀人行为。结局里他仍富有且未被写成被定罪，财富能召集服务与保镖，却不能在坠机海难中让他的血肉比别人更安全。',
'成功烧毁发明资料，海难中获救；承认毁屋与压制技术，但命案另有凶手，后续司法结果未写。','商业资源与秘密施压','通过企业、人员和资金安排收购、监视及暴力代理，亲自识别并毁掉藏在包柄的软片。','财富依赖实际组织执行；不是自动获得所有保镖技能，海难中同样须救生衣与他人救援。',[(710,736,'财力、企业及动机底色。'),(1624,1668,'取得皮包与烧毁软片。'),(2180,2188,'海上身体与获救条件。'),(2264,2342,'目的、炸屋及未主使命案。'),(2462,2474,'真正杀人命令的证实。')],
'保护已有产业与持续扩张，把损害别人的行为解释成经营上的必要。',[('新技术威胁旧有产业','有资金可买控制权','优先收购封存而不是承担转型损失。'),('掌握资料的人拒绝交易','认为秘密即将流出','使用代理施压，并把暴力后果推给执行范围。'),('敌人救了自己','不得不承认私人恩情','道谢或提出赔偿，但未必改变商业价值判断。')],roles=('反派',),scores=(1,0,2,2,2,2),tier='并')
make('wei_bo_linuo','韦勃·李诺',B,
'韦勃·李诺是五十四岁的电脑机构研究员，外貌比档案年龄显老，长期研究使他不太注意衣着保养。他把电脑系统装入汽车，让车辆依据输入的道路资料自动行驶，并亲手造出一辆可工作的样车。他最初找白克劳，希望大规模生产，却发现富豪只想买断并压下技术，两人为此争执。来到东方后，他带着全部资料和样车，尝试与外国机构接洽，要求买方不只支付高价，还必须真正实现发明。当他得知接头者只是受托的犯罪集团，又坚持直接会见实际买家，触怒了掌控交易的人。他察觉生命受威胁后，把皮包匆忙交给安妮，凭听来的名声相信木兰花会保护它。包里的三本白纸误导了接手者，真正记录藏在握手中的软片上；样车还设了不愿技术落入敌手时的自毁装置。这些防护既体现他不肯屈从的决心，也造成信息无法及时理解与保存的后果。他被孙永泰派去的枪手从车中拖出杀害，车子自动驶走后爆炸，资料后来又被白克劳毁去。终局卡应保留他的技术知识与推广理想，但不自动恢复毁掉的实物，更不能让电脑汽车无限读取未知道路或以幽灵方式行动。',
'遭孙永泰所属杀手枪杀；样车自毁、资料遭焚毁，原作未见技术再次完成。','电脑自动汽车设计','把电脑控制与输入的道路资料连接，实现样车自动驾驶，另有防失窃的自毁设置。','依赖道路数据、实体机件与制造条件；最后样车和资料已毁，重建需时间资源，不能视为常备无人军队。',[(26,76,'匆忙交包与危险说明。'),(502,510,'档案身份和死亡线索。'),(2278,2334,'技术、推广争执与自毁。'),(2456,2474,'交易要求和被杀经过。')],
'让发明真正进入社会使用，拒绝只换来资金却永远被封存。',[('有人愿意购买技术','能够落实制造应用','积极谈条件并说明工作成果。'),('发现对方只想封存或转手','推广目标受到破坏','反悔拒绝并寻求其他渠道。'),('生命和资料同时受威胁','无可靠正式保护','把秘密交给信任的名人，同时可能因仓促留下难解线索。')],scores=(1,0,2,2,2,1),tier='并',dead=True)
make('mengdi','蒙蒂',B,
'蒙蒂是铁龙达珠宝公司的营业经理，同时担任铁龙达号游艇船长，隶属白克劳控制的商业体系。她善于以优雅外貌、商业礼貌和重要公司的名声接近别人，首次拜访木兰花时，拿真实筹备中的珠宝展览作为说辞，隐瞒了追索李诺资料的目的。木兰花拒绝受聘并直接指出她不诚实，使她从尴尬转为恼怒。她之后仍承担白克劳与调查者之间的接触工作，接电话、安排会面、携带装钱的化妆箱并转交皮包；手腕宝石镯还承担微型传音联系的作用。她会使用组织提供的设备，不代表她本人发明了这些装置，也没有证据显示独立指挥所有暴力行动。白克劳在酒店受保护时，她试图把直闯者挡在会面之外，接到老板指示又立即带路，清楚显示她的权力边界。专机失事后，她与其他乘客一样由木兰花救出，在船舱里回避救命恩人的目光并感到惭愧。听见老板被公开斥为冷酷，她惊讶于无人曾如此对他说话。结局没有写她辞职、悔改或被捕，卡中因此保留执行者的依附与新生的不安，让她可以因实际恩义重新评估命令，而不预设完整的道德转变。',
'海难获救后仍与白克劳同行，表现惭愧，后续职业与司法状态不详。','商务交涉、船只职务与隐蔽联络','以经理身份会谈、安排交接，使用组织配发的微型传音手镯；登记为游艇船长。','不能把珠宝公司和游艇视为个人全部资产；没有独立发明或超常战斗证据，态度受老板命令影响。',[(642,674,'隐瞒目的的拜访。'),(710,736,'经理、船长及隶属关系。'),(1286,1336,'阻挡会面、手镯与接受命令。'),(1606,1628,'交易交接。'),(2216,2250,'获救后惭愧。'),(2344,2350,'对老板受斥的反应。')],
'维持在富豪体系内的专业地位与体面，同时不能完全无视直接受过的恩惠。',[('需要接近戒备对象','有可信商业议题','用正式职位和事务掩护真实目的。'),('对方揭穿谎言','自信与体面受挫','短暂恼怒后等待新的指令或机会。'),('敌对者实际救了自己','恩义无法用商业关系解释','出现迟疑和惭愧，未必立即公开反叛。')],roles=('阶段性对立者',),scores=(1,0,1,2,1,1),tier='纸')
make('sun_yongtai','孙永泰',B,
'孙永泰绰号鳄鱼，是警方熟知却长期未能捕获的犯罪人物。他在雷声电影院地下室经营一个承接犯罪委托的集团，只要报酬合适，便让手下代做违法事务。此次外国间谍机构并未亲自与李诺公开接触，而是把购买资料的工作交给了他；这层代理关系正是命案被错误归到白克劳身上的原因之一。他让蔡杰等人出面谈判，李诺提出高价和必须推广发明的条件，得知面对的只是中间人后又要直接见实际机构。孙永泰没有继续谈判或退出委托，而是下令杀人。枪手将研究员拖下车射死，随后因无人驾驶汽车自行离去而惊慌，留下了误导调查的奇异现场。他的集团也试图挟持准备向警方供述的蔡杰，说明组织通过暴力维系秘密与服从。最终蔡杰提供藏身地，警方封锁戏院、炸开铁门并施放催泪弹，二十四人被迫出来。他是最后出来的人，仍立刻被多名高级警官认出并铐走。人物卡保存委托型犯罪首领的生意逻辑与报复倾向，但不把外国情报机关全部能力归给他，也不把二十四名被捕者当作永远可随身召唤的兵力。',
'地下据点被警方攻破，随集团成员被捕，足够犯罪证据被搜出。','委托犯罪组织与灭口指挥','组织接头、承接外部犯罪委托并向手下下达杀人命令，使用隐蔽据点。','依赖手下和保密；内部成员叛离能暴露据点，催泪气体与警方包围可以迫使投降。',[(2436,2464,'身份、组织、委托与杀人命令。'),(2474,2508,'执行经过和据点被捕。')],
'把非法服务变成持续获利的生意，消灭妨碍交易或泄密的变量。',[('外部机构提出违法委托','报酬符合要求','安排中间人和执行者，隐藏客户。'),('交易对象拒绝代理条件','认为控制权被挑战','转向暴力而非继续商谈。'),('内部人员准备供述','据点仍需保密','试图回收或压制叛离者，可能因此加速暴露。')],roles=('反派',),aliases=('鳄鱼',),scores=(2,0,1,2,2,2),tier='并')
make('cai_jie','蔡杰',B,
'蔡杰是孙永泰犯罪集团的成员，也是奉命与李诺洽购发明资料的两名代表之一。他知道买方实际上是外国间谍机构，亲历李诺坚持技术必须付诸使用以及拒绝只同代理交涉的过程，却不是文本指认的两名杀人枪手之一。后来他与集团闹翻，想取得五万元报酬远走，以命案真相和集团藏身地向警方交换利益。高翔没有私下承诺固定金额，而是提醒他，叛离者已经危险，得到警方保护比先谈报酬更现实。他仍害怕直接走进警局，听说由木兰花来接才稍安心。等待期间两名同伙已经找到并夹住他，假装亲密地把他往车边带；木兰花突然袭击一侧挟持者，他也趁机挣脱并一拳打倒另一人。这种有限反击说明他不是全无行动能力，却不能推成足以单独对抗组织的高手。获救后，他终于同意进入警局，给出鳄鱼的身份、电影院地下室地址和李诺遇害经过，促成整个据点被捕。结局未交代他的奖金、刑责或今后去向，卡保留利益与求生共同驱动的投诚，不把他粉饰成自始正义的卧底，也不因作证抹去此前参与非法交易的责任。',
'获救后在警局供述，集团据点被攻破；个人奖金与司法处置未写明。','犯罪内幕与机会性反击','掌握交易和据点信息，能在同伴协助制造空隙时挣脱并出拳反击。','情报来自亲历和成员转述，非全知；脱离组织后易被追杀，需要警方或可信援助。',[(2352,2384,'索酬、叛离和保护需求。'),(2390,2432,'被挟持、反击和获救。'),(2450,2478,'详细供述与留下记录。')],
'脱离已经闹翻的犯罪组织，借掌握的消息取得安全和远走的资金。',[('与组织关系破裂','手中还有有价线索','试探警方能否提供金钱和保护。'),('有人要求直接进警局','担心途中被同伙杀害','选择可信中间人接应。'),('外援打破挟持','出现可利用的短暂空隙','自己配合反击，随后接受保护。')],roles=('阶段性对立者','单书主角'),scores=(2,0,0,1,1,1),tier='纸')
cov(B,[('白克劳','bai_kelau','反派','毁坏技术、炸屋及利益逻辑。'),('韦勃·李诺','wei_bo_linuo','单书主角','发明与拒绝封存导致主线。'),('蒙蒂','mengdi','阶段性对立者','受命伪装接近、交接资料与保护老板。'),('孙永泰','sun_yongtai','反派','代理交易及命案主使。'),('蔡杰','cai_jie','阶段性对立者','犯罪交易参与后叛离供述。'),('高翔','mulanhua_gao_xiang','系列主角','警方调查与围捕。'),('安妮','mulanhua_annie','系列主角','接包、避爆与受伤恢复。'),('穆秀珍','mulanhua_mu_xiuzhen','系列主角','探望及终局判断。'),('云五风','mulanhua_yun_wufeng','跨书重要配角','安妮牵挂与互动。')],excluded=[('齐警官、机组、救援军官、现场证人与匿名执行者','辅助调查、救援或缺乏独立身份的执行人员；犯罪首领和具名成员已纳入。')],notes=['标题冷血为道德评价，不是白克劳具有变温动物生理或冰能力。','自动汽车是实体电脑控制设备，事故不构成鬼车；白克劳不是已证实的李诺杀人主使。'])
